-- programmes: JSON list of the public support programmes a company's signals name (incubation at
-- each incubator, DPIIT recognition, BIRAC, DST, TDB, MeitY, iDEX, EXIM Bank, National Startup
-- Awards), counted and never ranked. programme_count is its length; organisation_count counts one
-- per organisation that published its own decision. Recomputed by the Worker from stored signals
-- on every ingest (src/programmes.ts); filled here for today's rows by ingest/programmes.py.
ALTER TABLE companies ADD COLUMN programmes TEXT;
ALTER TABLE companies ADD COLUMN programme_count INTEGER NOT NULL DEFAULT 0;
ALTER TABLE companies ADD COLUMN organisation_count INTEGER NOT NULL DEFAULT 0;

